// ============================================
// VALIDATION INPUT - Google Drive OCR
// RFC-014 compliant extraction
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing only, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- REQUIRED fields ---
const googleAccessToken = body.google_access_token || ctx.google_access_token;
const fileId = body.file_id || ctx.file_id || null;
const folderId = body.folder_id || ctx.folder_id || null;

if (!googleAccessToken) {
  errors.push('google_access_token requis');
}
if (!fileId && !folderId) {
  errors.push('file_id ou folder_id requis');
}

// --- Optional fields with defaults ---
const mistralApiKey = body.mistral_api_key || ctx.mistral_api_key || '';
const maxFiles = body.max_files || ctx.max_files || 100;
const includeImages = body.include_images || ctx.include_images || false;

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  google_access_token: googleAccessToken,
  mistral_api_key: mistralApiKey,
  file_id: fileId,
  folder_id: folderId,
  max_files: maxFiles,
  include_images: includeImages,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// FORMAT LIST OUTPUT - with _trace
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime;

const files = input.files || [];

return {
  success: true,
  operation: 'list_files',
  data: {
    files: files,
    folder_id: prevData.folder_id
  },
  meta: {
    provider: 'google_drive',
    count: files.length
  },
  _trace: {
    service_response: { file_count: files.length },
    provider: 'google_drive',
    mode: 'list',
    latency_ms: Date.now() - startTime,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request
};

// ============================================
// FORMAT OCR OUTPUT - with _trace
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const metadata = $('Get File Metadata').first().json;
const startTime = prevData.startTime;

const pages = input.pages || [];
const text = pages.map(p => p.markdown).join('\n\n') || '';

return {
  success: true,
  operation: 'ocr',
  data: {
    text: text,
    pages: pages,
    file: {
      id: prevData.file_id,
      name: metadata.name,
      mimeType: metadata.mimeType
    }
  },
  meta: {
    provider: 'mistral',
    model: input.model || 'mistral-ocr-latest',
    usage: {
      pages_processed: input.usage_info?.pages_processed || 1,
      doc_size_bytes: input.usage_info?.doc_size_bytes || 0
    }
  },
  _trace: {
    service_response: {
      pages_processed: input.usage_info?.pages_processed || pages.length,
      text_length: text.length
    },
    provider: 'mistral',
    mode: 'ocr',
    latency_ms: Date.now() - startTime,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request
};
